// Checks the reading sent by the ESP32 and forwards it to the Iryo backend.
const b = msg.payload;
const bad = (status, code, text) => {
    msg.statusCode = status;
    msg.payload = { code: code, message: text };
    return [null, msg];
};
const isText = (v, max) => typeof v === "string" && v.trim().length > 0 && v.length <= max;
const inRange = (v, lo, hi) => typeof v === "number" && isFinite(v) && v >= lo && v <= hi;
const given = (v) => v !== undefined && v !== null;

if (!b || typeof b !== "object" || Array.isArray(b)) return bad(400, "BAD_PAYLOAD", "Body must be a JSON object.");
if (!isText(b.deviceId, 80)) return bad(400, "BAD_PAYLOAD", "deviceId is required.");
if (!isText(b.deviceKey, 200)) return bad(400, "BAD_PAYLOAD", "deviceKey is required.");
if (!inRange(b.spo2Percent, 50, 100)) return bad(400, "BAD_PAYLOAD", "spo2Percent must be a number from 50 to 100.");
if (!inRange(b.temperatureC, 25, 45)) return bad(400, "BAD_PAYLOAD", "temperatureC must be a number from 25 to 45.");
if (given(b.heartRateBpm) && !inRange(b.heartRateBpm, 30, 220)) return bad(400, "BAD_PAYLOAD", "heartRateBpm must be a number from 30 to 220.");
if (given(b.heightCm) && !inRange(b.heightCm, 50, 250)) return bad(400, "BAD_PAYLOAD", "heightCm must be a number from 50 to 250.");
if (given(b.measuredAt) && (typeof b.measuredAt !== "string" || isNaN(Date.parse(b.measuredAt)))) return bad(400, "BAD_PAYLOAD", "measuredAt must be an ISO time.");
if (given(b.messageId) && !isText(b.messageId, 128)) return bad(400, "BAD_PAYLOAD", "messageId is invalid.");

const base = env.get("IRYO_BACKEND_URL");
if (!base) {
    node.error("IRYO_BACKEND_URL is not set");
    return bad(503, "UNAVAILABLE", "Service is not configured.");
}

const out = { deviceId: b.deviceId.trim(), spo2Percent: b.spo2Percent, temperatureC: b.temperatureC };
if (given(b.heartRateBpm)) out.heartRateBpm = b.heartRateBpm;
if (given(b.heightCm)) out.heightCm = b.heightCm;
if (given(b.measuredAt)) out.measuredAt = b.measuredAt;
if (given(b.messageId)) out.messageId = b.messageId;

msg.method = "POST";
msg.url = base.replace(/\/+$/, "") + "/api/ingest/measurements";
msg.headers = { "Content-Type": "application/json", "Accept": "application/json", "X-Device-Key": b.deviceKey };
msg.requestTimeout = 65000;
msg.payload = out;
return [msg, null];

// Passes the backend answer back to the device. 5xx and non-JSON answers become 502 so the device retries.
const status = Number(msg.statusCode) || 502;
const body = msg.payload;
if (status >= 500 || typeof body !== "object" || body === null) {
    msg.statusCode = 502;
    msg.payload = { code: "BACKEND_UNAVAILABLE", message: "The server is not ready. Retry shortly." };
    return msg;
}
msg.statusCode = status;
return msg;

// The backend did not answer (for example it is asleep). Tell the device to retry.
node.warn("Backend unreachable: " + (msg.error && msg.error.message));
msg.statusCode = 502;
msg.payload = { code: "BACKEND_UNAVAILABLE", message: "The server is waking up. Retry shortly." };
return msg;

// Wakes the backend: asks its health endpoint. The device calls this until backend is true.
const base = env.get("IRYO_BACKEND_URL");
if (!base) {
    msg.statusCode = 200;
    msg.payload = { ok: true, service: "nodered", backend: false };
    return [null, msg];
}
msg.method = "GET";
msg.url = base.replace(/\/+$/, "") + "/api/health";
msg.headers = { "Accept": "application/json" };
msg.requestTimeout = 8000;
msg.payload = "";
return [msg, null];

// Always answers 200 so the device knows Node-RED itself is awake. backend says whether the backend is ready.
const ok = Number(msg.statusCode) === 200 && msg.payload && typeof msg.payload === "object" && msg.payload.status === "ok";
msg.statusCode = 200;
msg.payload = { ok: true, service: "nodered", backend: ok };
return msg;

msg.statusCode = 200;
msg.payload = { ok: true, service: "nodered", backend: false };
return msg;

// Cheap check for Render and cron jobs. Does not touch the backend.
msg.statusCode = 200;
msg.payload = { ok: true, service: "nodered" };
return msg;
